def semver_sort(versions):
    def parse(v):
        core = v
        build = None
        if '+' in core:
            core, build = core.split('+', 1)
        pre = None
        if '-' in core:
            core, pre = core.split('-', 1)
        major, minor, patch = (int(x) for x in core.split('.'))
        if pre is not None:
            idents = pre.split('.')
        else:
            idents = None
        return (major, minor, patch, idents)

    def ident_key(ident):
        if ident.isdigit():
            return (0, int(ident))
        else:
            return (1, ident)

    def cmp_key(v):
        major, minor, patch, idents = parse(v)
        if idents is None:
            pre_flag = 1
            idents_key = []
        else:
            pre_flag = 0
            idents_key = [ident_key(i) for i in idents]
        return (major, minor, patch, pre_flag, idents_key)

    class Wrap:
        __slots__ = ('v', 'k')
        def __init__(self, v):
            self.v = v
            self.k = cmp_key(v)
        def __lt__(self, other):
            return self.k < other.k

    return [w.v for w in sorted((Wrap(v) for v in versions), key=lambda w: w.k)]

